package ir.hamrahyar.app;
import android.app.*;import android.content.*;import android.os.*;
public class ReminderReceiver extends BroadcastReceiver {
 @Override public void onReceive(Context context,Intent intent){String title=intent.getStringExtra("title");if(title==null||title.trim().isEmpty())title="Hamrah-Yar";String channel="hamrah_yar_reminders";NotificationManager nm=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);if(nm==null)return;if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(channel,"Hamrah-Yar reminders",NotificationManager.IMPORTANCE_DEFAULT);nm.createNotificationChannel(c);}Intent launch=new Intent(context,MainActivity.class);PendingIntent content=PendingIntent.getActivity(context,0,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(context,channel):new Notification.Builder(context);Notification n=b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("همراه‌یار").setContentText(title).setAutoCancel(true).setContentIntent(content).build();nm.notify((int)(System.currentTimeMillis()%Integer.MAX_VALUE),n);}
}